/**
 * 改造自 shadcn 原装 base-lyra sheet（https://ui.shadcn.com/r/styles/base-lyra/sheet.json，MIT）。
 * 与上游的差异：
 * 1. 动效改由 `motion` 属性选预设（ADR 0021）。`Sheet` 收 `motion`，经 context 交给 `SheetContent`；
 *    抽屉渲染 `data-motion`，方向由已有的 `data-side` 决定，遮罩固定用 `fade`。删掉抽屉上的过渡类
 *    （`transition duration-200 ease-in-out`、起止的 `opacity-0` 与各方向的 `translate-*-[2.5rem]`）
 *    和遮罩上的过渡类（`transition-opacity duration-150`、起止的 `opacity-0`）。
 * 2. import 改成消费者落点：Button 取 `@/components/ui/button`，关闭图标直接用 lucide 的 `XIcon`
 *    （上游写图标占位组件，由 shadcn add 换成 lucide，结果相同）。
 * 3. 删掉 `SheetTitle` 上的 `cn-font-heading`：它是 shadcn 的标题字体标记，本系统不用标题字体（ADR 0004）。
 * 此外只有格式化与一条 Biome 豁免注释，其余类名逐字保留。
 */
"use client";

import { Dialog as SheetPrimitive } from "@base-ui/react/dialog";
import { cn } from "cn";
import { XIcon } from "lucide-react";
import { type ComponentProps, createContext, use } from "react";

import { Button } from "@/components/ui/button";

/**
 * 抽屉支持的动效预设（ADR 0021）。缺省 `slide`。
 * - `slide`：从 `side` 那一侧整宽滑入并淡入，240ms；关闭 200ms。
 * - `fade`：只淡入淡出，150ms。
 */
type SheetMotion = "fade" | "slide";

const SheetMotionContext = createContext<SheetMotion>("slide");

function Sheet({
  motion = "slide",
  ...props
}: SheetPrimitive.Root.Props & { motion?: SheetMotion }) {
  return (
    <SheetMotionContext value={motion}>
      <SheetPrimitive.Root data-slot="sheet" {...props} />
    </SheetMotionContext>
  );
}

function SheetTrigger({ ...props }: SheetPrimitive.Trigger.Props) {
  return <SheetPrimitive.Trigger data-slot="sheet-trigger" {...props} />;
}

function SheetClose({ ...props }: SheetPrimitive.Close.Props) {
  return <SheetPrimitive.Close data-slot="sheet-close" {...props} />;
}

function SheetPortal({ ...props }: SheetPrimitive.Portal.Props) {
  return <SheetPrimitive.Portal data-slot="sheet-portal" {...props} />;
}

function SheetOverlay({ className, ...props }: SheetPrimitive.Backdrop.Props) {
  return (
    <SheetPrimitive.Backdrop
      data-slot="sheet-overlay"
      data-motion="fade"
      className={cn(
        // biome-ignore lint/plugin: 与上游逐字一致的遮罩色。遮罩在亮暗两种模式下都是压暗，不随主题换色。
        "fixed inset-0 z-50 bg-black/10 text-xs/relaxed supports-backdrop-filter:backdrop-blur-xs",
        className,
      )}
      {...props}
    />
  );
}

function SheetContent({
  className,
  children,
  side = "right",
  showCloseButton = true,
  ...props
}: SheetPrimitive.Popup.Props & {
  side?: "top" | "right" | "bottom" | "left";
  showCloseButton?: boolean;
}) {
  const motion = use(SheetMotionContext);
  return (
    <SheetPortal>
      <SheetOverlay />
      <SheetPrimitive.Popup
        data-slot="sheet-content"
        data-side={side}
        data-motion={motion}
        className={cn(
          "fixed z-50 flex flex-col bg-popover bg-clip-padding text-xs/relaxed text-popover-foreground shadow-lg data-[side=bottom]:inset-x-0 data-[side=bottom]:bottom-0 data-[side=bottom]:h-auto data-[side=bottom]:border-t data-[side=left]:inset-y-0 data-[side=left]:left-0 data-[side=left]:h-full data-[side=left]:w-3/4 data-[side=left]:border-r data-[side=right]:inset-y-0 data-[side=right]:right-0 data-[side=right]:h-full data-[side=right]:w-3/4 data-[side=right]:border-l data-[side=top]:inset-x-0 data-[side=top]:top-0 data-[side=top]:h-auto data-[side=top]:border-b data-[side=left]:sm:max-w-sm data-[side=right]:sm:max-w-sm",
          className,
        )}
        {...props}
      >
        {children}
        {showCloseButton && (
          <SheetPrimitive.Close
            data-slot="sheet-close"
            render={<Button variant="ghost" className="absolute top-3 right-3" size="icon-sm" />}
          >
            <XIcon />
            <span className="sr-only">Close</span>
          </SheetPrimitive.Close>
        )}
      </SheetPrimitive.Popup>
    </SheetPortal>
  );
}

function SheetHeader({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="sheet-header"
      className={cn("flex flex-col gap-0.5 p-4", className)}
      {...props}
    />
  );
}

function SheetFooter({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="sheet-footer"
      className={cn("mt-auto flex flex-col gap-2 p-4", className)}
      {...props}
    />
  );
}

function SheetTitle({ className, ...props }: SheetPrimitive.Title.Props) {
  return (
    <SheetPrimitive.Title
      data-slot="sheet-title"
      className={cn("text-sm font-medium text-foreground", className)}
      {...props}
    />
  );
}

function SheetDescription({ className, ...props }: SheetPrimitive.Description.Props) {
  return (
    <SheetPrimitive.Description
      data-slot="sheet-description"
      className={cn("text-xs/relaxed text-muted-foreground", className)}
      {...props}
    />
  );
}

export {
  Sheet,
  SheetClose,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  type SheetMotion,
  SheetTitle,
  SheetTrigger,
};
